const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Marovoay geometry (Madagascar, northwest region)
  const marovoayCoords = [46.4297, -16.3937];
  const point = ee.Geometry.Point(marovoayCoords);
  const aoi = point.buffer(5000); // 5km buffer around town

  // 2. Sentinel-2 collection with cloud masking function
  const maskClouds = function(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000);
  };

  // 3. Get images for January 27, 2020
  const col2020 = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(aoi)
    .filterDate('2020-01-25', '2020-01-29')
    .map(maskClouds);

  const size2020 = col2020.size().getInfo();
  print('2020-01-27 Images found: ' + size2020);

  if (size2020 === 0) {
    print('C1: No images for 2020-01-27');
    return;
  }

  // 4. Get images for January 18, 2017
  const col2017 = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(aoi)
    .filterDate('2017-01-16', '2017-01-20')
    .map(maskClouds);

  const size2017 = col2017.size().getInfo();
  print('2017-01-18 Images found: ' + size2017);

  if (size2017 === 0) {
    print('C1: No images for 2017-01-18');
    return;
  }

  // 5. Calculate NDWI for 2020
  const img2020 = col2020.median();
  const ndwi2020 = img2020.normalizedDifference(['B8', 'B11']);
  const waterMask2020 = ndwi2020.gt(0.3);

  const waterCount2020 = waterMask2020.reduceRegion(
    {reducer: ee.Reducer.sum(), geometry: aoi, scale: 30, maxPixels: 1e9}
  ).get('nd').getInfo();

  print('2020-01-27 Water pixels: ' + waterCount2020);

  // 6. Calculate NDWI for 2017
  const img2017 = col2017.median();
  const ndwi2017 = img2017.normalizedDifference(['B8', 'B11']);
  const waterMask2017 = ndwi2017.gt(0.3);

  const waterCount2017 = waterMask2017.reduceRegion(
    {reducer: ee.Reducer.sum(), geometry: aoi, scale: 30, maxPixels: 1e9}
  ).get('nd').getInfo();

  print('2017-01-18 Water pixels: ' + waterCount2017);

  // 7. Validation
  if (waterCount2020 === null || waterCount2017 === null) {
    print('C3: Calculation failed - null result');
    return;
  }

  if (waterCount2020 === 0 && waterCount2017 === 0) {
    print('C2: No valid water pixels in both dates');
    return;
  }

  // 8. Comparison
  const comparison = 'Water extent comparison - 2020: ' + waterCount2020 + ', 2017: ' + waterCount2017;
  print(comparison);

  if (waterCount2020 > waterCount2017) {
    print('A');
  } else {
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
